 1→import { Controller, Get, Res } from '@nestjs/common';
 2→import { Response } from 'express';
 3→import { ApiExcludeController } from '@nestjs/swagger';
 4→import { MetricsService } from './metrics.service';
 5→
 6→@ApiExcludeController()
 7→@Controller('metrics')
 8→export class MetricsController {
 9→  constructor(private readonly metricsService: MetricsService) {}
10→
11→  @Get()
12→  async getMetrics(@Res() res: Response): Promise<void> {
13→    const metrics = await this.metricsService.getMetrics();
14→    res.set('Content-Type', this.metricsService.getContentType());
15→    res.send(metrics);
16→  }
17→}
