 1→import { Module, Global } from '@nestjs/common';
 2→import { TypeOrmModule } from '@nestjs/typeorm';
 3→import { MetricsService } from './metrics.service';
 4→import { MetricsController } from './metrics.controller';
 5→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
 6→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
 7→import { User } from '../auth/entities/user.entity';
 8→import { IpnsRepublishSchedule } from '../republish/republish-schedule.entity';
 9→
10→@Global()
11→@Module({
12→  imports: [TypeOrmModule.forFeature([PinnedCid, FolderIpns, User, IpnsRepublishSchedule])],
13→  providers: [MetricsService],
14→  controllers: [MetricsController],
15→  exports: [MetricsService],
16→})
17→export class MetricsModule {}
