  1→import {
  2→  Injectable,
  3→  HttpException,
  4→  HttpStatus,
  5→  BadRequestException,
  6→  ConflictException,
  7→  Logger,
  8→  Inject,
  9→  forwardRef,
 10→} from '@nestjs/common';
 11→import { InjectRepository } from '@nestjs/typeorm';
 12→import { Repository } from 'typeorm';
 13→import { FolderIpns } from './entities/folder-ipns.entity';
 14→import {
 15→  PublishIpnsDto,
 16→  PublishIpnsResponseDto,
 17→  BatchPublishIpnsDto,
 18→  BatchPublishIpnsResponseDto,
 19→} from './dto';
 20→import { RepublishService } from '../republish/republish.service';
 21→import { DelegatedRoutingClient } from './delegated-routing.client';
 22→import { parseIpnsRecord } from './ipns-record-parser';
 23→
 24→@Injectable()
 25→export class IpnsService {
 26→  private readonly logger = new Logger(IpnsService.name);
 27→
 28→  constructor(
 29→    @InjectRepository(FolderIpns)
 30→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 31→    private readonly delegatedRouting: DelegatedRoutingClient,
 32→    @Inject(forwardRef(() => RepublishService))
 33→    private readonly republishService: RepublishService
 34→  ) {}
 35→
 36→  /**
 37→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 38→   * and track the folder in the database for TEE republishing
 39→   */
 40→  async publishRecord(userId: string, dto: PublishIpnsDto): Promise<PublishIpnsResponseDto> {
 41→    // Validate base64 record
 42→    let recordBytes: Uint8Array;
 43→    try {
 44→      recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 45→    } catch {
 46→      throw new BadRequestException('Invalid base64-encoded record');
 47→    }
 48→
 49→    // Save to DB first so resolve always has a fallback, even if delegated
 50→    // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 51→    const folder = await this.upsertFolderIpns(
 52→      userId,
 53→      dto.ipnsName,
 54→      dto.metadataCid,
 55→      dto.encryptedIpnsPrivateKey,
 56→      dto.keyEpoch,
 57→      'folder',
 58→      dto.expectedSequenceNumber
 59→    );
 60→
 61→    // Publish to delegated routing API (best-effort — DB is the reliable source)
 62→    try {
 63→      await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
 64→    } catch (error) {
 65→      this.logger.warn(
 66→        `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 67→      );
 68→    }
 69→
 70→    return {
 71→      success: true,
 72→      ipnsName: dto.ipnsName,
 73→      sequenceNumber: folder.sequenceNumber,
 74→    };
 75→  }
 76→
 77→  /**
 78→   * Batch publish multiple IPNS records with concurrency-limited processing.
 79→   * Supports partial success: individual record failures do not fail the batch.
 80→   * Processes up to 10 records concurrently.
 81→   */
 82→  async publishBatch(
 83→    userId: string,
 84→    dto: BatchPublishIpnsDto
 85→  ): Promise<BatchPublishIpnsResponseDto> {
 86→    const results: PublishIpnsResponseDto[] = [];
 87→    let totalSucceeded = 0;
 88→    let totalFailed = 0;
 89→
 90→    const CONCURRENCY = 10;
 91→
 92→    // Process records in batches of CONCURRENCY
 93→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
 94→      const batch = dto.records.slice(i, i + CONCURRENCY);
 95→
 96→      const settled = await Promise.allSettled(
 97→        batch.map(async (entry) => {
 98→          // Validate base64 record
 99→          let recordBytes: Uint8Array;
100→          try {
101→            recordBytes = Uint8Array.from(atob(entry.record), (c) => c.charCodeAt(0));
102→          } catch {
103→            throw new BadRequestException(`Invalid base64-encoded record for ${entry.ipnsName}`);
104→          }
105→
106→          // Save to DB first so resolve always has a fallback
107→          const folder = await this.upsertFolderIpns(
108→            userId,
109→            entry.ipnsName,
110→            entry.metadataCid,
111→            entry.encryptedIpnsPrivateKey,
112→            entry.keyEpoch,
113→            entry.recordType ?? 'folder',
114→            entry.expectedSequenceNumber
115→          );
116→
117→          // Publish to delegated routing (best-effort)
118→          try {
119→            await this.delegatedRouting.publish(entry.ipnsName, recordBytes);
120→          } catch (error) {
121→            this.logger.warn(
122→              `Delegated routing publish failed for ${entry.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
123→            );
124→          }
125→
126→          return {
127→            success: true,
128→            ipnsName: entry.ipnsName,
129→            sequenceNumber: folder.sequenceNumber,
130→          } as PublishIpnsResponseDto;
131→        })
132→      );
133→
134→      for (let j = 0; j < settled.length; j++) {
135→        const result = settled[j];
136→        if (result.status === 'fulfilled') {
137→          results.push(result.value);
138→          totalSucceeded++;
139→        } else {
140→          const reason = result.reason;
141→          // If any record (especially a folder record) has a conflict, fail the entire batch
142→          if (reason instanceof ConflictException) {
143→            throw reason;
144→          }
145→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
146→          this.logger.warn(
147→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
148→          );
149→          results.push({
150→            success: false,
151→            ipnsName,
152→            sequenceNumber: '0',
153→          });
154→          totalFailed++;
155→        }
156→      }
157→    }
158→
159→    return { results, totalSucceeded, totalFailed };
160→  }
161→
162→  /**
163→   * Create or update a folder/file IPNS entry.
164→   * Handles both folder metadata and per-file metadata IPNS records.
165→   */
166→  private async upsertFolderIpns(
167→    userId: string,
168→    ipnsName: string,
169→    metadataCid: string,
170→    encryptedIpnsPrivateKey?: string,
171→    keyEpoch?: number,
172→    recordType: 'folder' | 'file' = 'folder',
173→    expectedSequenceNumber?: string
174→  ): Promise<FolderIpns> {
175→    const existing = await this.getFolderIpns(userId, ipnsName);
176→
177→    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
178→    if (existing && expectedSequenceNumber !== undefined) {
179→      const expected = BigInt(expectedSequenceNumber);
180→      const current = BigInt(existing.sequenceNumber);
181→      if (expected !== current) {
182→        throw new ConflictException({
183→          statusCode: 409,
184→          message: 'Sequence number mismatch: folder was modified by another device',
185→          currentSequenceNumber: existing.sequenceNumber,
186→          expectedSequenceNumber,
187→        });
188→      }
189→    }
190→
191→    if (existing) {
192→      // Update existing entry
193→      existing.latestCid = metadataCid;
194→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
195→      existing.recordType = recordType;
196→      existing.updatedAt = new Date();
197→
198→      // Only update encrypted key if provided (e.g., on key rotation)
199→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
200→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
201→        existing.keyEpoch = keyEpoch;
202→      }
203→
204→      const saved = await this.folderIpnsRepository.save(existing);
205→
206→      // Auto-enroll for TEE republishing when encrypted key is provided
207→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
208→        this.republishService
209→          .enrollFolder(
210→            userId,
211→            ipnsName,
212→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
213→            keyEpoch,
214→            metadataCid,
215→            saved.sequenceNumber
216→          )
217→          .catch((err) =>
218→            this.logger.warn(
219→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
220→            )
221→          );
222→      }
223→
224→      return saved;
225→    }
226→
227→    // Create new entry — sequence starts at '1' to match the IPNS record
228→    // the client signed (clients compute newSeq = 0n + 1n = 1n for first publish).
229→    const folder = this.folderIpnsRepository.create({
230→      userId,
231→      ipnsName,
232→      latestCid: metadataCid,
233→      sequenceNumber: '1',
234→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
235→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
236→        : null,
237→      keyEpoch: keyEpoch ?? null,
238→      isRoot: false, // Root folder is tracked in Vault entity
239→      recordType,
240→    });
241→
242→    const saved = await this.folderIpnsRepository.save(folder);
243→
244→    // Auto-enroll for TEE republishing when encrypted key is provided
245→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
246→      this.republishService
247→        .enrollFolder(
248→          userId,
249→          ipnsName,
250→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
251→          keyEpoch,
252→          metadataCid,
253→          saved.sequenceNumber
254→        )
255→        .catch((err) =>
256→          this.logger.warn(
257→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
258→          )
259→        );
260→    }
261→
262→    return saved;
263→  }
264→
265→  /**
266→   * Get a folder IPNS entry by user and IPNS name
267→   */
268→  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
269→    return this.folderIpnsRepository.findOne({
270→      where: { userId, ipnsName },
271→    });
272→  }
273→
274→  /**
275→   * Get all folder IPNS entries for a user (for TEE republishing)
276→   */
277→  async getAllFolderIpns(userId: string): Promise<FolderIpns[]> {
278→    return this.folderIpnsRepository.find({
279→      where: { userId },
280→      order: { createdAt: 'ASC' },
281→    });
282→  }
283→
284→  /**
285→   * Resolve an IPNS name to its current CID via delegated routing,
286→   * falling back to the DB-cached CID when delegated routing is unavailable
287→   * or when the record is not found in the DHT.
288→   * Returns null if the IPNS name is not found anywhere (404)
289→   */
290→  async resolveRecord(ipnsName: string): Promise<{
291→    cid: string;
292→    sequenceNumber: string;
293→    signatureV2?: string;
294→    data?: string;
295→    pubKey?: string;
296→  } | null> {
297→    let result: {
298→      cid: string;
299→      sequenceNumber: string;
300→      signatureV2?: string;
301→      data?: string;
302→      pubKey?: string;
303→    } | null = null;
304→
305→    try {
306→      const recordBytes = await this.delegatedRouting.resolve(ipnsName);
307→      if (recordBytes) {
308→        result = this.parseIpnsRecordBytes(recordBytes);
309→        this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
310→      }
311→    } catch (error) {
312→      // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
313→      if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
314→        this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
315→      } else {
316→        throw error;
317→      }
318→    }
319→
320→    // Always check DB cache — it's written synchronously during publish
321→    // and may be ahead of the network (delegated routing can serve stale records)
322→    const cached = await this.folderIpnsRepository.findOne({
323→      where: { ipnsName },
324→    });
325→
326→    if (result && cached?.latestCid) {
327→      // Both sources available — prefer the one with the higher sequence number
328→      const networkSeq = BigInt(result.sequenceNumber);
329→      const dbSeq = BigInt(cached.sequenceNumber);
330→      if (dbSeq > networkSeq) {
331→        this.logger.log(
332→          `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
333→        );
334→        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
335→      }
336→      return result;
337→    }
338→
339→    if (result) {
340→      return result;
341→    }
342→
343→    // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
344→    if (cached?.latestCid) {
345→      this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
346→      return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
347→    }
348→
349→    return null;
350→  }
351→
352→  /**
353→   * Parse an IPNS record to extract CID and sequence number
354→   * Uses inline protobuf decoder — no external dependencies
355→   */
356→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
357→    cid: string;
358→    sequenceNumber: string;
359→    signatureV2?: string;
360→    data?: string;
361→    pubKey?: string;
362→  } {
363→    try {
364→      const record = parseIpnsRecord(recordBytes);
365→
366→      // Extract CID from the Value field (format: /ipfs/<cid>)
367→      const valuePath = record.value;
368→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
369→      if (!cidMatch) {
370→        this.logger.error('Failed to extract CID from IPNS record value');
371→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
372→      }
373→
374→      const cid = cidMatch[1];
375→      const sequenceNumber = String(record.sequence ?? 0n);
376→
377→      // Base64-encode signature fields if present
378→      const signatureV2 = record.signatureV2
379→        ? Buffer.from(record.signatureV2).toString('base64')
380→        : undefined;
381→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
382→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
383→
384→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
385→      return { cid, sequenceNumber, signatureV2, data, pubKey };
386→    } catch (error) {
387→      if (error instanceof HttpException) {
388→        throw error;
389→      }
390→      this.logger.error(`Failed to parse IPNS record: ${error}`);
391→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
392→    }
393→  }
394→}
