 1→// Grafana Alloy configuration for CipherBox staging.
 2→// Ships Docker container logs to Grafana Cloud Loki
 3→// and scrapes Prometheus metrics to Grafana Cloud Mimir.
 4→
 5→// ============================================================
 6→// LOG COLLECTION
 7→// ============================================================
 8→
 9→// Discover Docker containers via the Docker socket
10→discovery.docker "containers" {
11→  host = "unix:///var/run/docker.sock"
12→}
13→
14→// Relabel to extract useful metadata as log labels
15→discovery.relabel "containers" {
16→  targets = discovery.docker.containers.targets
17→
18→  rule {
19→    source_labels = ["__meta_docker_container_name"]
20→    target_label  = "container"
21→  }
22→
23→  rule {
24→    source_labels = ["__meta_docker_container_label_com_docker_compose_service"]
25→    target_label  = "service"
26→  }
27→
28→  rule {
29→    source_labels = ["__meta_docker_container_label_com_docker_compose_project"]
30→    target_label  = "project"
31→  }
32→}
33→
34→// Collect logs from discovered containers
35→loki.source.docker "containers" {
36→  host    = "unix:///var/run/docker.sock"
37→  targets = discovery.relabel.containers.output
38→
39→  forward_to = [loki.write.grafana_cloud.receiver]
40→}
41→
42→// Ship to Grafana Cloud Loki
43→loki.write "grafana_cloud" {
44→  endpoint {
45→    url = env("GRAFANA_LOKI_URL")
46→
47→    basic_auth {
48→      username = env("GRAFANA_LOKI_USERNAME")
49→      password = env("GRAFANA_LOKI_API_KEY")
50→    }
51→  }
52→}
53→
54→// ============================================================
55→// PROMETHEUS METRICS SCRAPING
56→// ============================================================
57→
58→// Scrape CipherBox API /metrics endpoint every 30 seconds
59→prometheus.scrape "cipherbox_api" {
60→  targets = [{
61→    __address__ = "api:3000",
62→  }]
63→  metrics_path = "/metrics"
64→  scrape_interval = "30s"
65→
66→  forward_to = [prometheus.remote_write.grafana_cloud.receiver]
67→}
68→
69→// Ship metrics to Grafana Cloud Mimir (Prometheus-compatible)
70→prometheus.remote_write "grafana_cloud" {
71→  endpoint {
72→    url = env("GRAFANA_PROMETHEUS_URL")
73→
74→    basic_auth {
75→      username = env("GRAFANA_PROMETHEUS_USERNAME")
76→      password = env("GRAFANA_PROMETHEUS_API_KEY")
77→    }
78→  }
79→}
