  1→import { Injectable, Logger } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { Repository, In, LessThanOrEqual } from 'typeorm';
  4→import { IpnsRepublishSchedule } from './republish-schedule.entity';
  5→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  6→import { TeeService, RepublishEntry, RepublishResult } from '../tee/tee.service';
  7→import { TeeKeyStateService } from '../tee/tee-key-state.service';
  8→import { DelegatedRoutingClient } from '../ipns/delegated-routing.client';
  9→
 10→/** Max entries per TEE request -- increased for per-file IPNS scalability (file records are smaller payloads) */
 11→const BATCH_SIZE = 100;
 12→
 13→/** After this many consecutive failures, mark entry as 'stale' */
 14→const MAX_CONSECUTIVE_FAILURES = 10;
 15→
 16→/** Republish interval in hours */
 17→const REPUBLISH_INTERVAL_HOURS = 6;
 18→
 19→/** Max backoff cap in seconds */
 20→const MAX_BACKOFF_SECONDS = 3600;
 21→
 22→/** Base backoff in seconds */
 23→const BASE_BACKOFF_SECONDS = 30;
 24→
 25→@Injectable()
 26→export class RepublishService {
 27→  private readonly logger = new Logger(RepublishService.name);
 28→
 29→  constructor(
 30→    @InjectRepository(IpnsRepublishSchedule)
 31→    private readonly scheduleRepository: Repository<IpnsRepublishSchedule>,
 32→    @InjectRepository(FolderIpns)
 33→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 34→    private readonly teeService: TeeService,
 35→    private readonly teeKeyStateService: TeeKeyStateService,
 36→    private readonly delegatedRouting: DelegatedRoutingClient
 37→  ) {}
 38→
 39→  /**
 40→   * Query entries that are due for republishing.
 41→   * Returns entries where status is 'active' or 'retrying' and next_republish_at <= now.
 42→   */
 43→  async getDueEntries(): Promise<IpnsRepublishSchedule[]> {
 44→    return this.scheduleRepository.find({
 45→      where: {
 46→        status: In(['active', 'retrying']),
 47→        nextRepublishAt: LessThanOrEqual(new Date()),
 48→      },
 49→      order: { nextRepublishAt: 'ASC' },
 50→      take: 2000,
 51→    });
 52→  }
 53→
 54→  /**
 55→   * Main orchestration: process all due republish entries.
 56→   * Batches entries, sends to TEE for signing, publishes signed records.
 57→   */
 58→  async processRepublishBatch(): Promise<{
 59→    processed: number;
 60→    succeeded: number;
 61→    failed: number;
 62→  }> {
 63→    const dueEntries = await this.getDueEntries();
 64→
 65→    if (dueEntries.length === 0) {
 66→      this.logger.debug('No entries due for republishing');
 67→      return { processed: 0, succeeded: 0, failed: 0 };
 68→    }
 69→
 70→    this.logger.log(`Processing ${dueEntries.length} due republish entries`);
 71→
 72→    // Soft capacity warning for large vaults with many per-file IPNS records
 73→    if (dueEntries.length > 1000) {
 74→      this.logger.warn(
 75→        `High IPNS record count: ${dueEntries.length} entries due for republishing - approaching capacity limits`
 76→      );
 77→    }
 78→
 79→    // Fetch current TEE epoch state for the batch
 80→    const teeState = await this.teeKeyStateService.getCurrentState();
 81→    if (!teeState) {
 82→      this.logger.error('TEE key state not initialized, cannot process republish batch');
 83→      return { processed: dueEntries.length, succeeded: 0, failed: dueEntries.length };
 84→    }
 85→
 86→    const currentEpoch = teeState.currentEpoch;
 87→    const previousEpoch = teeState.previousEpoch;
 88→
 89→    let totalSucceeded = 0;
 90→    let totalFailed = 0;
 91→
 92→    // Split into batches of BATCH_SIZE
 93→    for (let i = 0; i < dueEntries.length; i += BATCH_SIZE) {
 94→      const batch = dueEntries.slice(i, i + BATCH_SIZE);
 95→
 96→      // Build RepublishEntry payloads for TEE
 97→      const teeEntries: RepublishEntry[] = batch.map((entry) => ({
 98→        encryptedIpnsKey: entry.encryptedIpnsKey.toString('base64'),
 99→        keyEpoch: entry.keyEpoch,
100→        ipnsName: entry.ipnsName,
101→        latestCid: entry.latestCid,
102→        sequenceNumber: entry.sequenceNumber,
103→        currentEpoch,
104→        previousEpoch,
105→      }));
106→
107→      let teeResults: RepublishResult[];
108→      try {
109→        teeResults = await this.teeService.republish(teeEntries);
110→      } catch (error) {
111→        // TEE unreachable -- mark entire batch as failed
112→        const message = error instanceof Error ? error.message : String(error);
113→        this.logger.error(`TEE worker unreachable: ${message}`);
114→
115→        for (const entry of batch) {
116→          await this.handleEntryFailure(entry, `TEE unreachable: ${message}`);
117→        }
118→        totalFailed += batch.length;
119→        continue;
120→      }
121→
122→      // Process results
123→      for (let j = 0; j < batch.length; j++) {
124→        const entry = batch[j];
125→        const result = teeResults[j];
126→
127→        if (!result) {
128→          await this.handleEntryFailure(entry, 'No result from TEE worker');
129→          totalFailed++;
130→          continue;
131→        }
132→
133→        if (result.success && result.signedRecord && result.newSequenceNumber) {
134→          // TEE signing succeeded -- now publish to delegated routing
135→          try {
136→            await this.publishSignedRecord(entry.ipnsName, result.signedRecord);
137→
138→            // Update schedule entry on success
139→            entry.sequenceNumber = result.newSequenceNumber;
140→            entry.lastRepublishAt = new Date();
141→            entry.consecutiveFailures = 0;
142→            entry.status = 'active';
143→            entry.lastError = null;
144→            entry.nextRepublishAt = this.nextRepublishTime();
145→
146→            // Handle epoch upgrade if TEE re-encrypted with current epoch
147→            if (result.upgradedEncryptedKey && result.upgradedKeyEpoch !== undefined) {
148→              entry.encryptedIpnsKey = Buffer.from(result.upgradedEncryptedKey, 'base64');
149→              entry.keyEpoch = result.upgradedKeyEpoch;
150→              this.logger.log(
151→                `Epoch upgrade for ${entry.ipnsName}: epoch ${entry.keyEpoch} -> ${result.upgradedKeyEpoch}`
152→              );
153→            }
154→
155→            await this.scheduleRepository.save(entry);
156→
157→            // Keep FolderIpns sequence number in sync
158→            await this.syncFolderIpnsSequence(
159→              entry.userId,
160→              entry.ipnsName,
161→              result.newSequenceNumber
162→            );
163→
164→            totalSucceeded++;
165→          } catch (publishError) {
166→            // TEE signing succeeded but publishing failed (RESEARCH.md pitfall 6)
167→            const message =
168→              publishError instanceof Error ? publishError.message : String(publishError);
169→            this.logger.warn(
170→              `Signing succeeded but publish failed for ${entry.ipnsName}: ${message}`
171→            );
172→            await this.handleEntryFailure(
173→              entry,
174→              `Publish failed after successful signing: ${message}`
175→            );
176→            totalFailed++;
177→          }
178→        } else {
179→          // TEE signing failed
180→          await this.handleEntryFailure(entry, result.error || 'Unknown TEE error');
181→          totalFailed++;
182→        }
183→      }
184→    }
185→
186→    this.logger.log(
187→      `Republish batch complete: processed=${dueEntries.length}, succeeded=${totalSucceeded}, failed=${totalFailed}`
188→    );
189→
190→    return {
191→      processed: dueEntries.length,
192→      succeeded: totalSucceeded,
193→      failed: totalFailed,
194→    };
195→  }
196→
197→  /**
198→   * Publish a signed IPNS record to delegated routing with retries.
199→   */
200→  async publishSignedRecord(ipnsName: string, signedRecordBase64: string): Promise<void> {
201→    const recordBytes = Uint8Array.from(atob(signedRecordBase64), (c) => c.charCodeAt(0));
202→    await this.delegatedRouting.publish(ipnsName, recordBytes);
203→    this.logger.debug(`Signed IPNS record published for ${ipnsName}`);
204→  }
205→
206→  /**
207→   * Enroll or update a folder for TEE republishing.
208→   * Called when a folder is published with TEE-encrypted IPNS key.
209→   */
210→  async enrollFolder(
211→    userId: string,
212→    ipnsName: string,
213→    encryptedIpnsKey: Buffer,
214→    keyEpoch: number,
215→    latestCid: string,
216→    sequenceNumber: string
217→  ): Promise<void> {
218→    const existing = await this.scheduleRepository.findOne({
219→      where: { userId, ipnsName },
220→    });
221→
222→    if (existing) {
223→      // Update existing enrollment
224→      existing.encryptedIpnsKey = encryptedIpnsKey;
225→      existing.keyEpoch = keyEpoch;
226→      existing.latestCid = latestCid;
227→      existing.sequenceNumber = sequenceNumber;
228→      existing.nextRepublishAt = this.nextRepublishTime();
229→      await this.scheduleRepository.save(existing);
230→      this.logger.log(`Updated republish enrollment for ${ipnsName}`);
231→    } else {
232→      // Create new enrollment
233→      const schedule = this.scheduleRepository.create({
234→        userId,
235→        ipnsName,
236→        encryptedIpnsKey,
237→        keyEpoch,
238→        latestCid,
239→        sequenceNumber,
240→        nextRepublishAt: this.nextRepublishTime(),
241→        status: 'active',
242→        consecutiveFailures: 0,
243→        lastError: null,
244→        lastRepublishAt: null,
245→      });
246→      await this.scheduleRepository.save(schedule);
247→      this.logger.log(`Enrolled ${ipnsName} for TEE republishing (epoch ${keyEpoch})`);
248→    }
249→  }
