251→  /**
252→   * Unenroll an IPNS record from TEE republishing.
253→   * Called when files are deleted to prevent orphaned TEE enrollments.
254→   */
255→  async unenrollIpns(userId: string, ipnsName: string): Promise<void> {
256→    const result = await this.scheduleRepository.delete({ userId, ipnsName });
257→    if (result.affected && result.affected > 0) {
258→      this.logger.log(`Unenrolled ${ipnsName} from TEE republishing for user ${userId}`);
259→    } else {
260→      this.logger.debug(
261→        `No republish enrollment found for ${ipnsName} (user ${userId}) - nothing to unenroll`
262→      );
263→    }
264→  }
