266→  /**
267→   * Get aggregate health stats for admin endpoint.
268→   */
269→  async getHealthStats(): Promise<{
270→    pending: number;
271→    failed: number;
272→    stale: number;
273→    lastRunAt: Date | null;
274→    currentEpoch: number | null;
275→    teeHealthy: boolean;
276→  }> {
277→    const [pending, failed, stale] = await Promise.all([
278→      this.scheduleRepository.count({ where: { status: 'active' } }),
279→      this.scheduleRepository.count({ where: { status: 'retrying' } }),
280→      this.scheduleRepository.count({ where: { status: 'stale' } }),
281→    ]);
282→
283→    // Get most recent successful republish
284→    const lastRun = await this.scheduleRepository.findOne({
285→      where: { status: 'active' },
286→      order: { lastRepublishAt: 'DESC' },
287→    });
288→
289→    // Get current TEE epoch
290→    const teeState = await this.teeKeyStateService.getCurrentState();
291→
292→    // Check TEE worker health
293→    let teeHealthy = false;
294→    try {
295→      const health = await this.teeService.getHealth();
296→      teeHealthy = health.healthy;
297→    } catch {
298→      teeHealthy = false;
299→    }
300→
301→    return {
302→      pending,
303→      failed,
304→      stale,
305→      lastRunAt: lastRun?.lastRepublishAt ?? null,
306→      currentEpoch: teeState?.currentEpoch ?? null,
307→      teeHealthy,
308→    };
309→  }
310→
311→  /**
312→   * Reactivate all stale entries (e.g., when TEE recovers).
313→   * Resets status to 'active' with immediate next republish time.
314→   */
315→  async reactivateStaleEntries(): Promise<number> {
316→    const result = await this.scheduleRepository.update(
317→      { status: 'stale' },
318→      {
319→        status: 'active',
320→        consecutiveFailures: 0,
321→        nextRepublishAt: new Date(),
322→        lastError: null,
323→      }
324→    );
325→
326→    const count = result.affected ?? 0;
327→    if (count > 0) {
328→      this.logger.log(`Reactivated ${count} stale entries after TEE recovery`);
329→    }
330→    return count;
331→  }
332→
333→  /**
334→   * Handle a failed entry: increment failures, apply backoff or mark stale.
335→   */
336→  private async handleEntryFailure(
337→    entry: IpnsRepublishSchedule,
338→    errorMessage: string
339→  ): Promise<void> {
340→    entry.consecutiveFailures += 1;
341→    // NEVER log key material -- only ipnsName, epoch, and failure count
342→    entry.lastError = errorMessage.substring(0, 500);
343→
344→    if (entry.consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
345→      entry.status = 'stale';
346→      entry.nextRepublishAt = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000); // Far future
347→      this.logger.warn(
348→        `Entry ${entry.ipnsName} marked stale after ${entry.consecutiveFailures} failures`
349→      );
350→    } else {
351→      entry.status = 'retrying';
352→      const backoffSeconds = Math.min(
353→        BASE_BACKOFF_SECONDS * Math.pow(2, entry.consecutiveFailures),
354→        MAX_BACKOFF_SECONDS
355→      );
356→      entry.nextRepublishAt = new Date(Date.now() + backoffSeconds * 1000);
357→      this.logger.warn(
358→        `Entry ${entry.ipnsName} failed (${entry.consecutiveFailures}/${MAX_CONSECUTIVE_FAILURES}), retrying in ${backoffSeconds}s`
359→      );
360→    }
361→
362→    await this.scheduleRepository.save(entry);
363→  }
364→
365→  /**
366→   * Sync the FolderIpns sequence number after successful republish.
367→   * Handles both folder and per-file IPNS records (keyed by userId + ipnsName).
368→   */
369→  private async syncFolderIpnsSequence(
370→    userId: string,
371→    ipnsName: string,
372→    newSequenceNumber: string
373→  ): Promise<void> {
374→    try {
375→      await this.folderIpnsRepository.update(
376→        { userId, ipnsName },
377→        { sequenceNumber: newSequenceNumber }
378→      );
379→    } catch (error) {
380→      // Non-fatal: log and continue
381→      const message = error instanceof Error ? error.message : String(error);
382→      this.logger.warn(`Failed to sync FolderIpns sequence for ${ipnsName}: ${message}`);
383→    }
384→  }
385→
386→  /**
387→   * Calculate next republish time (now + 6 hours).
388→   */
389→  private nextRepublishTime(): Date {
390→    return new Date(Date.now() + REPUBLISH_INTERVAL_HOURS * 60 * 60 * 1000);
391→  }
392→}
